class Point {
public:
  // Constexpr constructor allows compile-time creation
  constexpr Point(double xVal = 0, double yVal = 0) noexcept
    : x(xVal), y(yVal)
  {}

  // Constexpr getters allow compile-time state queries
  constexpr double xValue() const noexcept { return x; }
  constexpr double yValue() const noexcept { return y; }

  // Non-constexpr setter for runtime modification
  void setX(double newX) noexcept { x = newX; }

private:
  double x, y;
};

// A constexpr object initialized with compile-time constants
constexpr Point p1(9.4, 27.7);
// Using a constexpr getter at compile-time
constexpr double x = p1.xValue();
